package dev.fold7.core

import org.junit.Assert.*
import org.junit.Test
import java.io.File

/** Only synthetic lavfi testsrc2 generated by the explicit Gradle fixture task. */
class FfmpegIntegrationTest {
    @Test fun generatedFileHasAudSpsPpsIdrAndMultipleSlicesPerAu() {
        val stream = fixture()
        val aus = TestStreams.collect(stream, listOf(stream.size), StreamLimits(maxQueuedAus = 3))
        assertEquals(3, aus.size)
        aus.forEachIndexed { index, au ->
            val nals = nals(au)
            val types = nals.map { it[0].toInt() and 31 }
            assertEquals(9, types.first())
            assertEquals(1, types.count { it == 9 })
            assertEquals(2, types.count { it == if (index == 0) 5 else 1 })
            if (index == 0) {
                assertTrue(types.contains(7))
                assertTrue(types.contains(8))
            }
        }
    }

    @Test fun generatedStreamIsInvariantAtEverySplitAndBytewise() {
        val stream = fixture()
        val limits = StreamLimits(maxQueuedAus = 3)
        val expected = TestStreams.collect(stream, listOf(stream.size), limits)
        for (split in 0..stream.size) {
            val actual = TestStreams.collect(stream, listOf(split, stream.size - split), limits)
            expected.zip(actual).forEach { (a, b) -> assertArrayEquals(a, b) }
            assertEquals(expected.size, actual.size)
        }
        val bytewise = TestStreams.collect(stream, List(stream.size) { 1 }, limits)
        assertEquals(expected.size, bytewise.size)
        expected.zip(bytewise).forEach { (a, b) -> assertArrayEquals(a, b) }
    }

    @Test fun removingAudFromGeneratedStreamIsRejected() {
        val noAud = TestStreams.annex(nals(fixture()).filter { it[0].toInt() and 31 != 9 })
        val assembler = AudAccessUnits()
        assertThrows(StreamRejected::class.java) {
            assembler.feed(noAud)
            assembler.finish()
        }
    }

    private fun fixture() = File(requireNotNull(System.getProperty("fixturePath"))).readBytes()

    private fun nals(bytes: ByteArray): List<ByteArray> {
        val nals = mutableListOf<ByteArray>()
        val splitter = AnnexBSplitter(256 * 1024, nals::add)
        splitter.feed(bytes)
        splitter.finish()
        return nals
    }
}
